"""The API index: every public name of the Python package, on one page.

    python .github/scripts/api_index.py            # rewrite the page
    python .github/scripts/api_index.py --check    # fail if it is stale

The page, `docs/reference/api-index.md`, is generated from the *installed*
`medh5` and committed, as `THIRD_PARTY_NOTICES` is from `Cargo.lock`: the docs
job installs only `docs/requirements.txt`, so a build hook cannot import the
package. One table per public module, one row per name in its `__all__`: the
name, its kind, the first sentence of its docstring and a link to the
hand-written section that documents it, where one exists.

A name is documented where a page outside the specification names it in code
--- an inline code span or a fenced block --- as a whole word, and its section
is the one that documents it best (`sections`).  Named with its module
(`medh5.task.SCHEMA`), it documents that object alone, under every module that
exports it, and not another module's name that is spelt the same.  A name no
page names is listed in `tests/project/undocumented_api.txt`, which may only
shrink: a pull request that adds a public name documents it.

Standard library only, besides the package itself.
"""

from __future__ import annotations

import argparse
import ast
import importlib
import inspect
import os
import pkgutil
import re
import sys
import typing
import unicodedata
import warnings
from collections.abc import Iterator
from dataclasses import dataclass
from pathlib import Path
from types import ModuleType
from typing import Any

ROOT = Path(__file__).resolve().parents[2]
DOCS = ROOT / "docs"
PAGE = DOCS / "reference" / "api-index.md"
UNDOCUMENTED = ROOT / "tests" / "project" / "undocumented_api.txt"
PACKAGE = "medh5"

# Where a name's section is looked for first: the reference, then the guides
# and tutorials, then anything else.  The specification is not a reference for
# this package's API, nor are the command line's and the Rust crate's pages
# (`medh5 pack` documents a command, not `medh5.collection.pack`), and the index
# does not document itself.
PAGES_FIRST = (
    "reference/",
    "guides/",
    "tutorials/",
    "explanation/",
    "",
)
EXCLUDED = (
    "spec/",
    "reference/api-index.md",
    "reference/cli.md",
    "reference/rust.md",
)

HEADER = """\
# API index

<!-- Generated by .github/scripts/api_index.py from the installed package. Do
not edit: run the script, which `--check` holds the page to. -->

Every public name of the Python package, one table per module: what it is, the
first sentence of its docstring, and the section of these pages that documents
it. A name exported by more than one module is listed under each. The full
signatures are in the docstrings (`help(name)`), and `medh5._core` is the
compiled extension the modules re-export from, not an API of its own.
"""


@dataclass(frozen=True)
class Row:
    module: str
    name: str
    kind: str
    summary: str
    section: Section | None

    @property
    def path(self) -> str:
        return f"{self.module}.{self.name}"


# --- the package ---


def modules() -> list[str]:
    package = importlib.import_module(PACKAGE)
    names = [PACKAGE]
    for info in pkgutil.walk_packages(package.__path__, PACKAGE + "."):
        if not any(part.startswith("_") for part in info.name.split(".")):
            names.append(info.name)
    return sorted(names)


def kind_of(value: Any) -> str:
    if inspect.ismodule(value):
        return "module"
    if typing.get_origin(value) is not None:
        return "type"
    if inspect.isclass(value):
        return "exception" if issubclass(value, BaseException) else "class"
    if callable(value):
        return "function"
    return "constant"


def own_doc(value: Any, kind: str) -> str:
    """The docstring the object was given, or "".

    A constant's `__doc__` is its type's, and a dataclass given none gets its
    own signature, which reads differently on each Python; neither is
    documentation.
    """
    if kind in ("constant", "type"):
        return ""
    doc = value.__doc__ if isinstance(value.__doc__, str) else ""
    if kind == "class" and doc.startswith(f"{value.__name__}("):
        return ""
    return inspect.cleandoc(doc) if doc else ""


def attribute_docs(module: ModuleType) -> dict[str, str]:
    """`NAME = ...` followed by a string literal: the attribute's docstring."""
    path = getattr(module, "__file__", None)
    if not path or not path.endswith(".py"):
        return {}
    body = ast.parse(Path(path).read_text(encoding="utf-8")).body
    out: dict[str, str] = {}
    for node, after in zip(body, body[1:], strict=False):
        if isinstance(node, ast.Assign) and len(node.targets) == 1:
            target = node.targets[0]
        elif isinstance(node, ast.AnnAssign):
            target = node.target
        else:
            continue
        if (
            isinstance(target, ast.Name)
            and isinstance(after, ast.Expr)
            and isinstance(after.value, ast.Constant)
            and isinstance(after.value.value, str)
        ):
            out[target.id] = inspect.cleandoc(after.value.value)
    return out


_ROLE = re.compile(r":[\w:]+:`~?([^`]+)`")


def summary(doc: str) -> str:
    """The first sentence of a docstring, as one Markdown table cell."""
    paragraph = doc.split("\n\n", 1)[0]
    text = " ".join(paragraph.split())
    text = _ROLE.sub(r"`\1`", text).replace("``", "`")
    # The package's docstrings write a dash as `---`; the pages may not.
    text = text.replace(" --- ", " — ").replace("---", "—")
    match = re.search(r"(?<=[.!?])\s+(?=[A-Z`(])", text)
    if match:
        text = text[: match.start()]
    # An unpaired backtick would run a code span into the next cell.
    if text.count("`") % 2:
        text = text.replace("`", "")
    # Markup outside code spans is escaped.  Inside them Markdown escapes it,
    # and a table does not split a cell at a bar in a code span.
    parts = text.split("`")
    for i in range(0, len(parts), 2):
        parts[i] = parts[i].replace("<", "&lt;").replace(">", "&gt;")
        parts[i] = parts[i].replace("|", r"\|")
    return "`".join(parts)


def exported() -> Iterator[tuple[str, str, Any]]:
    """(module, name, value) for every name in every public `__all__`."""
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        for module_name in modules():
            module = importlib.import_module(module_name)
            for name in module.__all__:
                yield module_name, name, getattr(module, name)


# --- the pages ---


def _slug(heading: str) -> str:
    """The anchor `pymdownx.slugs.slugify(case="lower")` gives a heading."""
    text = re.sub(r"\[([^\]]*)\]\([^)]*\)", r"\1", heading)
    text = re.sub(r"<[^>]+>", "", text).replace("`", "").replace("*", "")
    text = unicodedata.normalize("NFC", text).lower()
    return re.sub(r"[^\w\- ]", "", text).replace(" ", "-")


_HEADING = re.compile(r"^(#{1,6})\s+(.*?)\s*$")
_EXPLICIT = re.compile(r"\{\s*#([\w-]+)\s*\}\s*$")
_FENCE = re.compile(r"^\s*```(\w*)")
_SPAN = re.compile(r"`([^`\n]+)`")


def _tier(relative: str) -> int:
    for rank, prefix in enumerate(PAGES_FIRST):
        if relative.startswith(prefix):
            return rank
    return len(PAGES_FIRST)


def pages() -> list[str]:
    found = (p.relative_to(DOCS).as_posix() for p in DOCS.rglob("*.md"))
    return sorted(p for p in found if not p.startswith(EXCLUDED))


@dataclass(frozen=True)
class Section:
    page: str
    anchor: str  # "" for the page itself
    title: str  # the page's title, then the heading's text

    @property
    def target(self) -> str:
        return f"{self.page}#{self.anchor}" if self.anchor else self.page


def _plain(heading: str) -> str:
    """A heading's text as a link label: links and attributes dropped."""
    text = re.sub(r"\[([^\]]*)\]\([^)]*\)", r"\1", heading)
    return _EXPLICIT.sub("", text).strip()


def mentions(relative: str) -> Iterator[tuple[Section, str, bool]]:
    """(section, code, whether the code reads as a definition) for each piece
    of Python on a page: an inline code span, or a line of a `python` block.

    A definition is a heading, or the first cell of a table row: the shapes a
    page documents a name in (`sections` counts a call, `Name(`, as one too).
    """
    seen: dict[str, int] = {}
    fenced: str | None = None  # the open fence's language
    page_title = relative
    section = Section(relative, "", page_title)
    for line in (DOCS / relative).read_text(encoding="utf-8").splitlines():
        if fence := _FENCE.match(line):
            fenced = None if fenced is not None else fence.group(1)
            continue
        if fenced is not None:
            # Python names Python; a shell block names commands, which share
            # the functions' names (`medh5 pack`), and JSON names fields.
            if fenced in ("python", "pycon", "py"):
                yield section, line, False
            continue
        if heading := _HEADING.match(line):
            text = heading.group(2)
            if len(heading.group(1)) == 1:
                page_title = _plain(text).replace("`", "")
                section = Section(relative, "", page_title)
                continue
            if explicit := _EXPLICIT.search(text):
                anchor = explicit.group(1)
            else:
                # Python-Markdown makes a repeated anchor unique with `_1`, `_2`.
                slug = _slug(text)
                count = seen.get(slug, 0)
                seen[slug] = count + 1
                anchor = slug if count == 0 else f"{slug}_{count}"
            section = Section(relative, anchor, f"{page_title} › {_plain(text)}")
            yield section, text, True
            continue
        first_cell = line.lstrip().startswith("|")
        for index, span in enumerate(_SPAN.findall(line)):
            if span.startswith(("medh5 ", "-")):
                continue  # a command or a flag
            yield section, span, first_cell and index == 0


def resolve(dotted: str) -> Any:
    """The object a dotted path from the package names, or `_MISSING`.

    Attribute by attribute, as Python reads it: `medh5.dataset.check` is the
    function the package exports, not the submodule of that name, which is
    imported only where no attribute names it.
    """
    parts = dotted.split(".")
    try:
        value: Any = importlib.import_module(parts[0])
    except ImportError:
        return _MISSING
    for i, part in enumerate(parts[1:], start=2):
        found = getattr(value, part, _MISSING)
        if found is _MISSING and inspect.ismodule(value):
            try:
                found = importlib.import_module(".".join(parts[:i]))
            except ImportError:
                return _MISSING
        if found is _MISSING:
            return _MISSING
        value = found
    return value


_MISSING = object()
_DOTTED = re.compile(r"[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)*")


def _identity(name: str, value: object) -> object:
    """What a qualified mention of *name* documents: its object, or for a value
    Python may share between unrelated names (a small int, a string), that
    value under that name --- `CODES_REVISION` and `EXIT_USAGE` are both the
    int 2, and are one object."""
    if isinstance(value, (int, float, str, bytes, type(None))):
        return (name, type(value).__name__, repr(value))
    return id(value)


def sections(
    names: set[str], qualified: bool = False
) -> dict[str | tuple[str, object], Section]:
    """name -> the section that documents it best.

    The reference before the guides before anything else; then a section that
    names it as a definition (`mentions`) before one that only uses it; then
    the section naming it most often; then the first.  With *qualified*, a
    name written after its module's path (`medh5.task.SCHEMA`) is counted for
    that object, under the key `("object", _identity(name, value))`, not for
    the bare name.
    """
    tally: dict[str | tuple[str, object], dict[Section, list[int]]] = {}
    order = 0
    for relative in pages():
        for section, code, definition in mentions(relative):
            for dotted in _DOTTED.findall(code):
                parts = dotted.split(".")
                for i, word in enumerate(parts):
                    if word not in names:
                        continue
                    key: str | tuple[str, object] = word
                    if qualified and i and parts[0] == PACKAGE:
                        value = resolve(".".join(parts[: i + 1]))
                        if value is not _MISSING:
                            key = ("object", _identity(word, value))
                    called = definition or re.search(rf"\b{word}\(", code)
                    counts = tally.setdefault(key, {}).setdefault(
                        section, [0, 0, order]
                    )
                    counts[0] += 1 if called else 0
                    counts[1] += 1
                    order += 1
    return {
        name: min(
            found,
            key=lambda s: (
                _tier(s.page),
                -min(found[s][0], 1),
                -found[s][1],
                found[s][2],
            ),
        )
        for name, found in tally.items()
    }


# --- the index ---


def rows() -> list[Row]:
    entries = list(exported())
    docs: dict[str, dict[str, str]] = {
        m: attribute_docs(importlib.import_module(m)) for m in modules()
    }
    found = sections({name for _, name, _ in entries}, qualified=True)
    # A bare mention of a name two objects share (`load`, `SCHEMA`) cannot
    # say which it documents, so it documents neither: each needs its path.
    objects: dict[str, set[int]] = {}
    for _, name, value in entries:
        objects.setdefault(name, set()).add(id(value))
    out: list[Row] = []
    for module_name, name, value in entries:
        kind = kind_of(value)
        doc = own_doc(value, kind)
        if not doc and kind in ("constant", "type"):
            # Where the constant is defined, if not in the module exporting
            # it: a module whose attribute of that name is this object.
            owners = [module_name, *sorted(docs)]
            doc = next(
                (
                    docs[m][name]
                    for m in owners
                    if name in docs[m]
                    and getattr(sys.modules[m], name, _MISSING) is value
                ),
                "",
            )
        if kind == "constant":
            kind = f"constant (`{type(value).__name__}`)"
        candidates = [found.get(("object", _identity(name, value)))]
        if len(objects[name]) == 1:
            candidates.append(found.get(name))
        named = [c for c in candidates if c is not None]
        # The reference before the guides, whichever way the name was written.
        section = min(named, key=lambda s: _tier(s.page)) if named else None
        out.append(Row(module_name, name, kind, summary(doc), section))
    return out


def _link(section: Section) -> str:
    target = os.path.relpath(DOCS / section.page, PAGE.parent).replace(os.sep, "/")
    anchor = f"#{section.anchor}" if section.anchor else ""
    label = section.title.replace("|", r"\|")
    return f"[{label}]({target}{anchor})"


def render(index: list[Row]) -> str:
    out = [HEADER]
    by_module: dict[str, list[Row]] = {}
    for row in index:
        by_module.setdefault(row.module, []).append(row)
    for module_name in sorted(by_module):
        anchor = module_name.replace(".", "-")
        out += [
            "",
            f"## `{module_name}` {{ #{anchor} }}",
            "",
            "| Name | Kind | Summary | Documented in |",
            "|---|---|---|---|",
        ]
        for row in sorted(by_module[module_name], key=lambda r: r.name.lower()):
            where = _link(row.section) if row.section else ""
            out.append(f"| `{row.name}` | {row.kind} | {row.summary} | {where} |")
    return "\n".join(out) + "\n"


def undocumented(index: list[Row]) -> list[str]:
    return sorted(row.path for row in index if row.section is None)


def listed() -> list[str]:
    text = UNDOCUMENTED.read_text(encoding="utf-8")
    return [
        line.strip()
        for line in text.splitlines()
        if line.strip() and not line.startswith("#")
    ]


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description=__doc__.split("\n\n", 1)[0])
    parser.add_argument(
        "--check", action="store_true", help="fail if the page is stale"
    )
    args = parser.parse_args(argv)
    text = render(rows())
    if args.check:
        current = PAGE.read_text(encoding="utf-8") if PAGE.is_file() else ""
        if current != text:
            print(
                f"{PAGE.relative_to(ROOT)} is stale: run "
                "python .github/scripts/api_index.py",
                file=sys.stderr,
            )
            return 1
        return 0
    PAGE.write_text(text, encoding="utf-8")
    print(f"wrote {PAGE.relative_to(ROOT)}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
